using System.Reflection;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.EntityFrameworkCore.Migrations.Operations;

namespace MyApp.Domain.Models.SqlScriptMigrations;

/// <summary>
///     Base class of every migration. Runs the SQL scripts of the migration around the operations generated by EF Core.
/// </summary>
/// <remarks>
///     <para>
///         Scripts are embedded resources located in
///         <c>SqlScripts/&lt;MigrationId&gt;/Before/**/*.sql</c> (executed before the migration operations) and
///         <c>SqlScripts/&lt;MigrationId&gt;/After/**/*.sql</c> (executed after them), where <c>MigrationId</c> is the
///         migration file name without extension (for example <c>20261118093000_AddProduct</c>).
///     </para>
///     <para>
///         Inside each stage, scripts run in ordinal order of their relative path, so execution order is deterministic.
///         Prefix folders or files with numbers (<c>01_</c>, <c>02_</c>) to control it.
///         A script whose name ends with <c>.no-transaction.sql</c> runs outside of the migration transaction.
///     </para>
///     <para>
///         Scripts are injected as regular EF Core SQL operations, so they are part of every way of applying migrations
///         (<c>Database.MigrateAsync()</c>, <c>dotnet ef database update</c>, <c>dotnet ef migrations script</c>, bundles)
///         and batch separators (<c>GO</c>) are handled by the database provider. Scripts are not reverted by
///         <see cref="Migration.Down" />.
///     </para>
///     <para>
///         Generated migrations inherit this class automatically (see <see cref="SqlScriptMigrationsGenerator" />).
///     </para>
/// </remarks>
public abstract class SqlScriptMigration : Migration
{
    public const string ScriptsRoot = "SqlScripts";
    public const string NoTransactionSuffix = ".no-transaction.sql";

    private IReadOnlyList<MigrationOperation>? _upOperations;

    public override IReadOnlyList<MigrationOperation> UpOperations => _upOperations ??=
    [
        .. LoadScripts(SqlScriptStage.Before),
        .. base.UpOperations,
        .. LoadScripts(SqlScriptStage.After)
    ];

    private IEnumerable<MigrationOperation> LoadScripts(SqlScriptStage stage)
    {
        var migrationType = GetType();
        var migrationId = migrationType.GetCustomAttribute<MigrationAttribute>()?.Id
                          ?? throw new InvalidOperationException(
                              $"Migration '{migrationType.Name}' has no {nameof(MigrationAttribute)}.");

        var prefix = $"{ScriptsRoot}/{migrationId}/{stage}/";
        var assembly = migrationType.Assembly;

        return assembly.GetManifestResourceNames()
            .Select(name => (Name: name, Path: name.Replace('\\', '/')))
            .Where(x => x.Path.StartsWith(prefix, StringComparison.Ordinal)
                        && x.Path.EndsWith(".sql", StringComparison.OrdinalIgnoreCase))
            .OrderBy(x => x.Path, StringComparer.Ordinal)
            .Select(x => new SqlOperation
            {
                Sql = ReadResource(assembly, x.Name),
                SuppressTransaction = x.Path.EndsWith(NoTransactionSuffix, StringComparison.OrdinalIgnoreCase)
            })
            .ToArray();
    }

    private static string ReadResource(Assembly assembly, string name)
    {
        using var stream = assembly.GetManifestResourceStream(name)!;
        using var reader = new StreamReader(stream);

        return reader.ReadToEnd();
    }
}

public enum SqlScriptStage
{
    Before,
    After
}
